"""Extract exact CPC effect table bytes, without executing game code."""
from pathlib import Path
import base64, hashlib
from recover import disk_files, game_data_image

ROOT=Path(__file__).resolve().parents[1]
m=game_data_image(disk_files(ROOT/'Head over Heels (Europe).dsk'))
data=bytes(m[0xB8B:0x14A0])
b64=base64.b64encode(data).decode()
(ROOT/'src/OriginalAudioData.cs').write_text(
    '// Generated by tools/recover_audio.py from the supplied CPC disk.\n'
    '// Relocated 0B8B–149F; SHA256 '+hashlib.sha256(data).hexdigest()+'\n'
    'namespace HoH26;\ninternal static class OriginalAudioData\n{\n'
    '    internal static readonly byte[] Bytes = Convert.FromBase64String(\n'+
    '\n'.join('        "'+b64[i:i+100]+'"'+(' +' if i+100<len(b64) else ');') for i in range(0,len(b64),100))+'\n}\n')
print('CPC effect table SHA256:',hashlib.sha256(data).hexdigest())
